    ingredients:[{items:["8 ounces elbow macaroni or shells","½ cup mayonnaise","1 tablespoon lemon juice","1 teaspoon salt","1 teaspoon sugar","1 teaspoon celery seed","1 tomato, diced","1 cup celery, diced","3 tablespoons chopped pimiento","2 tablespoons chopped green pepper","Salad greens","Radish roses, to garnish"]}],
    steps:["Cook the macaroni as directed and drain. Rinse with cold water and drain again.","Mix the mayonnaise with the lemon juice, salt and sugar. Combine with the macaroni, celery seed, tomato, celery, pimiento and green pepper.","Serve on salad greens and garnish with radish roses."],
