    ingredients:[{name:"Dressing",items:["¾ cup buttermilk","¼ cup grated red onion","2 tablespoons cider vinegar","1 teaspoon sugar","½ teaspoon each salt and freshly ground pepper"]},{name:"Slaw",items:["3 cups shredded green cabbage (half a small head)","3 cups shredded red cabbage (half a small head)","1 cup shredded carrots"]}],
